-- # Lernfeld 5: Cyberphysische Systeme > ## Softwareplanung > - Lasten- und Pflichtenheft

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Lastenheft ohne Kundenbeteiligung vollständig erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kunden definieren Anforderungen"}, {"text": "Ja", "correct": false, "because": "Ohne Input fehlt Perspektive"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Pflichtenheft bindend für den Auftraggeber?', 2, '[{"text": "Nein", "correct": true, "because": "Es bindet den Auftragnehmer"}, {"text": "Ja", "correct": false, "because": "Pflichtenheft ist Lösungsvorschlag"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Lasten- und Pflichtenheft identische Inhalte haben?', 2, '[{"text": "Nein", "correct": true, "because": "Lastenheft beschreibt Was, Pflichtenheft Wie"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Pflichtenheft alle Details der technischen Umsetzung enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Es beschreibt Lösung, nicht Implementierung"}, {"text": "Ja", "correct": false, "because": "Details folgen im Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Lastenheft rechtlich abgesichert starten?', 2, '[{"text": "Nein", "correct": true, "because": "Lastenheft ist Basis für Vertrag"}, {"text": "Ja", "correct": false, "because": "Rechtliche Klarheit fehlt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wer erstellt typischerweise das Lastenheft?', 2, '[{"text": "Auftraggeber", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Auftragnehmer", "correct": false, "because": "Reagiert mit Pflichtenheft"}, {"text": "Projektleiter", "correct": false, "because": "Koordiniert, erstellt nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Pflichtenhefts?', 3, '[{"text": "Technische Lösung beschreiben", "correct": true, "because": "Wie wird umgesetzt"}, {"text": "Kundenwünsche formulieren", "correct": false, "because": "Lastenheft-Aufgabe"}, {"text": "Budget festlegen", "correct": false, "because": "Anderer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument dient als Grundlage für das Pflichtenheft?', 2, '[{"text": "Lastenheft", "correct": true, "because": "Pflichtenheft basiert darauf"}, {"text": "Projektplan", "correct": false, "because": "Zeitliche Planung"}, {"text": "Testprotokoll", "correct": false, "because": "Spätere Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen werden primär im Lastenheft festgelegt?', 2, '[{"text": "Funktionale Anforderungen", "correct": true, "because": "Was soll erreicht werden"}, {"text": "Technische Details", "correct": false, "because": "Pflichtenheft-Bereich"}, {"text": "Implementierungsstrategien", "correct": false, "because": "Nicht im Lastenheft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument wird bei Streitigkeiten rechtlich herangezogen?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Bindend für Auftragnehmer"}, {"text": "Lastenheft", "correct": false, "because": "Wunsch des Auftraggebers"}, {"text": "Anforderungsliste", "correct": false, "because": "Weniger formal"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören typischerweise ins Lastenheft?', 4, '[{"text": "Zieldefinition", "correct": true, "because": "Was soll erreicht werden"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Qualitätsaspekte"}, {"text": "Technische Spezifikationen", "correct": false, "because": "Pflichtenheft-Bereich"}, {"text": "Funktionale Anforderungen", "correct": true, "because": "Kern des Lastenhefts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind im Pflichtenheft enthalten?', 3, '[{"text": "Lösungsvorschläge", "correct": true, "because": "Wie wird umgesetzt"}, {"text": "Akzeptanzkriterien", "correct": true, "because": "Abnahme definiert"}, {"text": "Kundenwünsche", "correct": false, "because": "Lastenheft-Bereich"}, {"text": "Technische Umsetzung", "correct": true, "because": "Lösungsansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede bestehen zwischen Lasten- und Pflichtenheft?', 3, '[{"text": "Lastenheft vom Kunden, Pflichtenheft vom Entwickler", "correct": true, "because": "Rollenverteilung"}, {"text": "Lastenheft beschreibt Was, Pflichtenheft Wie", "correct": true, "because": "Fokus unterschiedlich"}, {"text": "Beide sind rechtlich bindend", "correct": false, "because": "Nur Pflichtenheft bindet"}, {"text": "Pflichtenheft ist optional", "correct": false, "because": "Beide essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch ein unvollständiges Lastenheft?', 4, '[{"text": "Missverständnisse", "correct": true, "because": "Unklarheit führt zu Fehlern"}, {"text": "Kostenüberschreitung", "correct": true, "because": "Nacharbeiten nötig"}, {"text": "Technische Perfektion", "correct": false, "because": "Widerspricht Mängeln"}, {"text": "Verzögerungen", "correct": true, "because": "Unklare Ziele bremsen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen ein Pflichtenheft verbindlich?', 3, '[{"text": "Technische Lösungsbeschreibung", "correct": true, "because": "Verpflichtet Umsetzung"}, {"text": "Abgestimmte Akzeptanzkriterien", "correct": true, "because": "Definiert Erfolg"}, {"text": "Kundenwünsche", "correct": false, "because": "Lastenheft-Bereich"}, {"text": "Vertragliche Zustimmung", "correct": true, "because": "Rechtliche Basis"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Lastenheft ist ein Angebot des Auftragnehmers. b) Das Pflichtenheft beschreibt die technische Lösung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Lastenheft vom Kunden, Pflichtenheft technisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Pflichtenheft ist für den Auftraggeber bindend. b) Das Lastenheft enthält funktionale Anforderungen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Pflichtenheft bindet Entwickler, Lastenheft spezifiziert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Lastenheft beschreibt die technische Umsetzung. b) Das Pflichtenheft ist Grundlage für die Abnahme.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Lastenheft nicht technisch, Pflichtenheft abnahme relevant"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Lasten- und Pflichtenheft sind rechtlich gleichwertig. b) Das Lastenheft wird vom Auftraggeber erstellt.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Pflichtenheft bindend, Lastenheft vom Kunden"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Pflichtenheft kann ohne Lastenheft erstellt werden. b) Beide Dokumente sind für große Projekte essenziell.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Pflichtenheft braucht Basis, beide wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

